function lesson9Dialogue(){app.innerHTML=intro('HỘI THOẠI · BÀI 9','Gợi ý đi chơi và những trải nghiệm đã có.','Hai hội thoại được chép lại từ các trang bạn gửi.')+lesson2VoiceControls()+'<button class="btn secondary" id="pinyin">'+(showPinyin?'Ẩn':'Hiện')+' pinyin</button>'+lesson9Data.dialogues.map(([title,lines],d)=>'<h2>'+title+'</h2><button class="btn secondary" data-lesson9-full="'+d+'">▶ Nghe toàn hội thoại</button>'+lines.map(([name,zh,py,vi],i)=>'<article class="dialogue"><small>'+name+'</small><button class="text-button" data-lesson9-line="'+d+','+i+'" aria-label="Nghe câu '+(i+1)+'">▶</button><p class="han">'+zh+'</p>'+(showPinyin?'<p class="pinyin">'+py+'</p>':'')+'<p>'+vi+'</p></article>').join('')).join('')+lesson9References(5,8);bindLesson2Voice(lesson9Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelector('#pinyin').onclick=()=>{stopWordAudio();showPinyin=!showPinyin;lesson9Dialogue();};document.querySelectorAll('[data-lesson9-line]').forEach(b=>b.onclick=()=>{const[d,i]=b.dataset.lesson9Line.split(',').map(Number);lesson2Speak(lesson9Data.dialogues[d][1][i][1]);});document.querySelectorAll('[data-lesson9-full]').forEach(b=>b.onclick=()=>lesson2Speak(lesson9Data.dialogues[Number(b.dataset.lesson9Full)][1].map(l=>l[1]).join(' ')));}
function lesson9BTNCMarkup(file){const group=lesson9BTNC.find(g=>g.file===file);if(!group)return '<p class="sub">File chính Q2B9; xem phần đáp án BTNC trên trang tham khảo bên dưới.</p>'+lesson9BTNCReference();const id=lesson9BTNC.indexOf(group),saved=state.lesson9Exercises?.['btnc'+id]||{};return '<details class="lesson2-answer-key"><summary>Luyện nghe với 5 câu hỏi</summary><p class="sub">Câu hỏi tự luyện biên soạn từ bản ghi lời nghe, không phải bộ lựa chọn của đề BTNC gốc.</p><form id="lesson9BTNCForm'+id+'">'+group.questions.map((q,i)=>'<fieldset class="question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l9nc'+id+'q'+i+'" value="'+j+'" '+(String(saved[i]?.answer)===String(j)?'checked':'')+'> '+v+'</label>').join('')+'<div id="lesson9BTNCFeedback'+id+'-'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson9BTNCResult'+id+'" role="status"></p></form></details><details class="lesson2-answer-key"><summary>Bản ghi lời nghe và đáp án BTNC gốc</summary>'+group.transcript.map((t,i)=>'<p lang="zh-CN" style="white-space:pre-line">'+(i+1)+'. '+esc(t)+'</p>').join('')+'<p><b>Đáp án '+group.title+':</b> '+group.key.map((k,i)=>(i+1)+'. '+k).join(' · ')+'</p><p class="sub">Các chữ cái dùng đối chiếu với đề BTNC gốc; câu tự luyện phía trên có thứ tự lựa chọn riêng.</p>'+lesson9BTNCReference()+'</details>';}
function lesson9BTNCReference(){return '<details class="lesson2-reference"><summary>Xem trang đáp án BTNC bài 9</summary><img loading="lazy" style="max-width:100%;height:auto" src="images/lesson9/btnc-answers-page20.png" alt="Đáp án BTNC bài 9, trang 20 của PDF"></details>';}
function bindLesson9BTNC(){lesson9BTNC.forEach((group,id)=>{document.querySelector('#lesson9BTNCForm'+id).onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;group.questions.forEach((q,i)=>{const answer=form.get('l9nc'+id+'q'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson9BTNCFeedback'+id+'-'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson9Exercises=state.lesson9Exercises||{};state.lesson9Exercises['btnc'+id]=records;save();document.querySelector('#lesson9BTNCResult'+id).textContent='Đúng '+count+' / 5 câu.';};});}

const lesson9SourcePages=["105","106","107","108","109","110","111","112","113","114","115","116"];
function lesson9References(first=1,last=12){return '<details class="lesson2-reference"><summary>Xem trang giáo trình gốc</summary>'+Array.from({length:last-first+1},(_,i)=>'<figure><img loading="lazy" src="images/lesson9/source-'+(first+i)+'.png" alt="Bài 9 · ảnh nguồn '+(first+i)+'"><figcaption>Trang '+lesson9SourcePages[first+i-1]+'</figcaption></figure>').join('')+'</details>';}
function lesson9Home(){app.innerHTML=intro('HSK2 · LESSON 9',lesson9Data.title,lesson9Data.pinyin+' · '+lesson9Data.vi)+'<section class="hero"><div><h2>Bạn đã từng thấy gấu trúc chưa?</h2><p>Hỏi trải nghiệm, xin gợi ý và lên kế hoạch cuối tuần.</p><a class="btn" href="#words">Học 19 mục từ →</a></div><div class="hero-mark" aria-hidden="true">过</div></section><div class="stats"><div class="stat"><small>TỪ ĐÃ NHỚ</small><strong>'+state.known.length+'<small> / 19</small></strong></div><div class="stat"><small>HỘI THOẠI</small><strong>02</strong></div><div class="stat"><small>TRANG GIÁO TRÌNH</small><strong>105–116</strong></div></div><div class="grid">'+[['words','Từ vựng','Nghe & gõ · Flashcard · Ghép từ'],['grammar','Ngữ pháp','过 · Đã từng và chưa từng'],['dialogue','Hội thoại','Sở thú · Bảo tàng và vịt quay'],['practice','Luyện tập','Điền từ · Đọc hiểu · Trải nghiệm · Phỏng vấn'],['listening','Luyện nghe','Bốn file Q2B9 · Bản ghi BTNC · Tự luyện'],['writing','Luyện viết','Chữ Hán trong bài 9']].map(([id,title,desc])=>'<a class="card card-link" href="#'+id+'"><h3>'+title+' ↗</h3><p>'+desc+'</p></a>').join('')+'</div><article class="card grammar"><h2>Khởi động</h2><p>在中国，你去过哪些很有名的地方？那些地方怎么样？<br>你吃过哪些很有名的中国菜？味道怎么样？<br>在你的国家什么很有名？给大家介绍一下。</p></article>'+lesson9References();}
function lesson9Grammar(){app.innerHTML=intro('NGỮ PHÁP · BÀI 9','Kể trải nghiệm với 过.','过 đứng sau động từ để nói đã từng có một trải nghiệm; thường đi cùng cảm nhận hoặc đánh giá.')+'<article class="card grammar"><h2>01 · Khẳng định</h2><div class="pattern">Chủ ngữ + động từ + 过 + (tân ngữ)</div><p lang="zh-CN">我吃过中国菜，很好吃。<br>海伦唱过中国歌，很好听。<br>他看过中国电影，很喜欢。</p><p class="sub">Tôi từng ăn món Trung, rất ngon. · Helen từng hát bài hát Trung Quốc, rất hay. · Anh ấy từng xem phim Trung Quốc và rất thích.</p></article><article class="card grammar"><h2>02 · Hai cách hỏi</h2><div class="pattern">V + 过 + (O) + 吗？<br>V + 没 + V + 过 + (O)？</div><p lang="zh-CN">你吃过中国菜吗？<br>你吃没吃过中国菜？<br>你听过中国歌吗？<br>你听没听过中国歌？</p></article><article class="card grammar"><h2>03 · Phủ định</h2><div class="pattern">没 + V + 过 + (O)<br>还没 + V + 过 + (O)</div><p>没……过: chưa từng. 还没……过: đến giờ vẫn chưa từng. Phủ định trải nghiệm vẫn giữ 过.</p><p lang="zh-CN">我没吃过中国菜。<br>我还没吃过中国菜。<br>我没听过中国歌。<br>我还没听过中国歌。</p><p class="sub">Phân biệt: 我吃过烤鸭。 — Tôi từng ăn vịt quay. 我今天吃了烤鸭。 — Hôm nay tôi đã ăn vịt quay.</p></article><article class="card grammar"><h2>Mẫu câu hữu ích</h2><p lang="zh-CN">你有什么建议？<br>我对动物很感兴趣。<br>你感兴趣的话，我们一起去吧。<br>味道好极了！</p></article><a class="btn" href="#practice">Luyện kể trải nghiệm →</a>'+lesson9References(3,5);}
