function lesson9Practice(){app.innerHTML=intro('LUYỆN TẬP · BÀI 9','Bạn đã từng trải nghiệm những gì?','Luyện 过 theo ảnh, đoạn đọc và phỏng vấn bạn học.')+'<div class="toolbar lesson2-modes">'+[['vocab','Điền từ'],['reading','Đọc hiểu'],['choose','过 · 了 · 没'],['pictures','Trải nghiệm theo ảnh'],['shop','Phỏng vấn bạn học'],['summary','Tự tổng kết']].map(([id,title])=>'<button class="btn '+(lesson9PracticeMode===id?'':'secondary')+'" data-lesson9-mode="'+id+'">'+title+'</button>').join('')+'</div><div id="lesson9ExerciseArea"></div>';document.querySelectorAll('[data-lesson9-mode]').forEach(b=>b.onclick=()=>{lesson9PracticeMode=b.dataset.lesson9Mode;lesson9Practice();});renderLesson9ExerciseArea();}
function renderLesson9ExerciseArea(){const area=document.querySelector('#lesson9ExerciseArea'),mode=lesson9PracticeMode;if(mode==='pictures'){renderLesson9Experiences(area);return;}if(mode==='shop'){renderLesson9Shop(area);return;}if(mode==='summary'){area.innerHTML='<article class="card grammar"><h2>Từ ngữ và mẫu câu muốn nhớ</h2><label for="lesson9SummaryWords">Từ ngữ</label><textarea id="lesson9SummaryWords" rows="4"></textarea><label for="lesson9SummaryPatterns">Mẫu câu</label><textarea id="lesson9SummaryPatterns" rows="4"></textarea><p class="sub">Tự động lưu trong tiến độ Lesson 9.</p></article>'+lesson9References(12,12);for(const[id,key]of [['lesson9SummaryWords','words'],['lesson9SummaryPatterns','patterns']]){document.querySelector('#'+id).value=state.lesson9Summary?.[key]||'';document.querySelector('#'+id).oninput=e=>{state.lesson9Summary=state.lesson9Summary||{};state.lesson9Summary[key]=e.target.value;save();};}return;}
 const saved=state.lesson9Exercises?.[mode]||{};
 area.innerHTML=(mode==='reading'?'<article class="card grammar"><h2>Đoạn đọc</h2><p class="lesson2-reading" lang="zh-CN">'+lesson9Data.reading+'</p><p class="sub">Từ hỗ trợ: 决定 (quyết định), 不感兴趣 (không hứng thú), 已经去过 (đã từng đến).</p></article>':'')+'<form id="lesson9ExerciseForm">'+lesson9Data.exercises[mode].map((q,i)=>'<article class="card grammar"><label for="lesson9Answer'+i+'">'+(i+1)+'. '+esc(q[0])+'</label><input class="lesson2-answer" id="lesson9Answer'+i+'" lang="zh-CN" placeholder="Gõ chữ Hán…" value="'+esc(saved[i]?.draft||'')+'"><div id="lesson9Feedback'+i+'" role="status"></div></article>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson9Result" role="status"></p></form>'+(mode==='reading'?'<h2>Chọn đáp án theo đoạn văn</h2><form id="lesson9ReadingQuiz">'+lesson9Data.exercises.comprehension.map((q,i)=>'<fieldset class="card question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l9reading'+i+'" value="'+j+'"> '+v+'</label>').join('')+'<div id="lesson9ReadingFeedback'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra đọc hiểu</button><p id="lesson9ReadingResult" role="status"></p></form>':'')+lesson9References(mode==='vocab'?2:10,mode==='vocab'?3:11);
 document.querySelector('#lesson9ExerciseForm').onsubmit=e=>{e.preventDefault();const records={};let count=0;lesson9Data.exercises[mode].forEach((q,i)=>{const draft=document.querySelector('#lesson9Answer'+i).value,r=gradeLesson9Exercise(mode,i,draft);records[i]={draft,correct:r.correct};count+=r.correct?1:0;document.querySelector('#lesson9Feedback'+i).innerHTML='<div class="feedback '+(r.correct?'good':'bad')+'">'+(r.correct?'✓ Chính xác':'Đáp án tham khảo: '+esc(r.answer))+'<br>'+esc(r.note)+'</div>';});state.lesson9Exercises=state.lesson9Exercises||{};state.lesson9Exercises[mode]=records;save();document.querySelector('#lesson9Result').textContent='Đúng '+count+' / '+lesson9Data.exercises[mode].length+' câu.';};
 if(mode==='reading')document.querySelector('#lesson9ReadingQuiz').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;lesson9Data.exercises.comprehension.forEach((q,i)=>{const answer=form.get('l9reading'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson9ReadingFeedback'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson9Exercises=state.lesson9Exercises||{};state.lesson9Exercises.comprehension=records;save();document.querySelector('#lesson9ReadingResult').textContent='Đúng '+count+' / '+lesson9Data.exercises.comprehension.length+' câu.';};
}

function lesson9Listening(){const groups=[{"title":"09-1 · Gợi ý đi sở thú","d":0,"tf":[["欧文去过很多好玩儿的地方。","Đúng."],["欧文周末想去动物园。","Đúng."],["文丽没去过动物园。","Sai — cô ấy đã đi."],["欧文想跟文丽一起去动物园。","Đúng."]],"questions":[["欧文看过什么电影？","《功夫熊猫》。"],["欧文对什么感兴趣？","动物。"],["文丽觉得动物园的熊猫怎么样？","可爱极了。"],["动物园在哪儿？","在郊区。"]]},{"title":"09-2 · Bảo tàng và vịt quay","d":1,"questions":[["欧文周末想去哪儿？","动物园。"],["海伦为什么不想去动物园？","她对动物不太感兴趣。"],["欧文吃没吃过烤鸭？","没吃过。"],["欧文现在想做什么？","现在就去吃烤鸭。"]]}];app.innerHTML=intro('LUYỆN NGHE · BÀI 9','Gợi ý đi chơi và những trải nghiệm đã có.','Bốn file Q2B9 bạn cung cấp, kèm bản ghi BTNC và câu tự luyện.')+'<div class="notice">Các file Q2B9 thuộc bộ BTNC. NC1–NC3 được đối chiếu với PDF bài 9. Chưa xác nhận bản thu tương ứng mã 09-1, 09-2, 09-3 trong giáo trình.</div>'+['Q2B9.mp3','Q2B9.NC1.MP3','Q2B9.NC2.MP3','Q2B9.NC3.MP3'].map((file,i)=>'<article class="card grammar"><h3>'+file+'</h3><audio controls preload="none" src="audio/'+file+'"></audio><label>Tốc độ <select data-lesson9-audio="'+i+'" aria-label="Tốc độ '+file+'"><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option></select></label>'+lesson9BTNCMarkup(file)+'</article>').join('')+'<h2>Luyện thêm theo văn bản giáo trình</h2>'+lesson2VoiceControls()+groups.map(g=>'<article class="card grammar"><h2>'+g.title+'</h2><button class="btn secondary" data-lesson9-listen="'+g.d+'">▶ Nghe toàn hội thoại bằng giọng thiết bị</button>'+(g.tf?'<h3>Đúng / sai</h3>'+g.tf.map(([q,a])=>'<details class="lesson2-answer-key"><summary>'+q+'</summary><p>'+a+'</p></details>').join(''):'')+'<h3>Nghe và trả lời</h3>'+g.questions.map(([q,a])=>'<details class="lesson2-answer-key"><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'<p class="sub">Đáp án theo văn bản hội thoại, không phải theo audio BTNC.</p></article>').join('')+'<article class="card grammar"><h2>09-3 · Bài nghe mở rộng</h2><p class="notice">Chưa xác nhận bản thu tương ứng 09-3 nên phần này chưa chấm điểm.</p><h3>Đúng / sai</h3><ol><li>海伦在美国学过汉语。</li><li>现在海伦每天都吃中国菜。</li><li>海伦没吃过烤鸭。</li><li>欧文建议海伦去博物馆。</li></ol><h3>Chọn đáp án</h3><ol><li>海伦是……留学生。<br>A. 美国　B. 日本　C. 英国</li><li>海伦在美国……<br>A. 吃过中国菜　B. 学过汉语　C. 看过中国电影</li><li>海伦下个周末打算……<br>A. 吃烤鸭，去博物馆　B. 吃烤鸭，看电影　C. 学汉语，去博物馆</li><li>海伦打算……跟朋友一起吃饭。<br>A. 下个星期天中午　B. 下个星期六晚上　C. 下个星期六中午</li></ol></article>'+lesson9References(9,10);bindLesson9BTNC();document.querySelectorAll('[data-lesson9-audio]').forEach(s=>s.onchange=()=>document.querySelectorAll('audio')[Number(s.dataset.lesson9Audio)].playbackRate=Number(s.value));document.querySelectorAll('audio').forEach(a=>a.onplay=()=>{stopWordAudio();document.querySelectorAll('audio').forEach(b=>{if(a!==b)b.pause();});});bindLesson2Voice(lesson9Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelectorAll('[data-lesson9-listen]').forEach(b=>b.onclick=()=>lesson2Speak(lesson9Data.dialogues[Number(b.dataset.lesson9Listen)][1].map(l=>l[1]).join(' ')));}
function renderLesson9Shop(area){const saved=state.lesson9Interview||{};area.innerHTML='<article class="card grammar"><h2>Phỏng vấn trải nghiệm</h2><p>Hỏi bạn học đã từng làm gì, làm khi nào hoặc ở đâu và cảm nhận thế nào. Nếu chưa từng, chuyển câu khác. Gợi ý: 参观博物馆、看熊猫、看京剧、吃烤鸭.</p>'+[['name','Tên bạn học','小明'],['action','Động từ','去'],['object','Nơi / đối tượng','长城'],['time','Khi nào','去年'],['place','Ở đâu (có thể bỏ trống)',''],['feeling','Cảm nhận','很长，很美']].map(([key,label,hint])=>'<label for="lesson9Interview'+key+'">'+label+'</label><input class="lesson2-answer" lang="zh-CN" id="lesson9Interview'+key+'" data-lesson9-interview="'+key+'" placeholder="'+hint+'" value="'+esc(saved[key]||'')+'">').join('')+'<button class="btn" id="lesson9InterviewMake">Tạo báo cáo tham khảo</button><p id="lesson9InterviewOutput" style="white-space:pre-line;line-height:2"></p></article>'+lesson9References(8,9);document.querySelectorAll('[data-lesson9-interview]').forEach(input=>input.oninput=e=>{state.lesson9Interview=state.lesson9Interview||{};state.lesson9Interview[input.dataset.lesson9Interview]=e.target.value;save();});document.querySelector('#lesson9InterviewMake').onclick=()=>{document.querySelector('#lesson9InterviewOutput').textContent=lesson9InterviewReport(state.lesson9Interview||{});};}
for(const[route,handler]of Object.entries({home:lesson9Home,grammar:lesson9Grammar,dialogue:lesson9Dialogue,practice:lesson9Practice,listening:lesson9Listening}))pages[route]=function(){if(state.lesson==='9')handler();else lesson9PreviousPages[route]();};
pages.writing=function(){lesson9PreviousPages.writing();if(state.lesson!=='9')return;document.querySelector('#app .eyebrow').textContent='LUYỆN VIẾT · BÀI 9';const chars=[...new Set(lesson9Data.rows.map(r=>r[0]).join('').split('').filter(c=>/[\u3400-\u9fff]/.test(c)))];document.querySelector('#model').innerHTML=chars.map(c=>'<option>'+c+'</option>').join('');document.querySelector('#modelchar').textContent=chars[0];};
const lesson9ExperienceTasks=[['看','熊猫'],['去','大学的图书馆'],['吃','烤鸭'],['看','京剧']];
function lesson9ExperienceVariants(index,kind){const[v,o]=lesson9ExperienceTasks[index];return kind===0?['你'+v+'过'+o+'吗','你'+v+'没'+v+'过'+o,'你有没有'+v+'过'+o]:kind===1?['我'+v+'过'+o,v+'过'+o,'我'+v+'过',v+'过']:['我没'+v+'过'+o,'我还没'+v+'过'+o,'没'+v+'过'+o,'还没'+v+'过'+o,'我没'+v+'过','没'+v+'过','还没'+v+'过'];}
function gradeLesson9Experience(index,kind,draft){return lesson9ExperienceVariants(index,kind).some(a=>compareHanzi(draft,a).correct);}
function renderLesson9Experiences(area){const saved=state.lesson9Exercises?.experiences||{};area.innerHTML='<article class="card grammar"><h2>Trải nghiệm theo ảnh</h2><p>Với mỗi ảnh, viết một câu hỏi và luyện cả hai cách trả lời: đã từng / chưa từng. Cảm nhận thật của bạn có thể ghi ở phần phỏng vấn.</p><div class="grid">'+[4,5].map(i=>'<img loading="lazy" src="images/lesson9/source-'+i+'.png" alt="Ảnh luyện trải nghiệm trang '+lesson9SourcePages[i-1]+'" style="max-width:100%;width:440px">').join('')+'</div>'+lesson9ExperienceTasks.map(([v,o],i)=>'<h3>'+(i+1)+'. '+v+o+'</h3>'+['Hỏi: bạn đã từng… chưa?','Trả lời: đã từng','Trả lời: chưa từng'].map((q,j)=>'<label for="lesson9Experience'+i+'-'+j+'">'+q+'</label><input class="lesson2-answer" lang="zh-CN" id="lesson9Experience'+i+'-'+j+'" value="'+esc(saved[i]?.drafts?.[j]||'')+'"><p id="lesson9ExperienceFeedback'+i+'-'+j+'" role="status"></p>').join('')+'<button class="btn secondary" data-lesson9-experience="'+i+'">Kiểm tra</button>').join('')+'</article>';document.querySelectorAll('[data-lesson9-experience]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.lesson9Experience),drafts=[],results=[];for(let j=0;j<3;j++){const draft=document.querySelector('#lesson9Experience'+i+'-'+j).value,correct=gradeLesson9Experience(i,j,draft);drafts.push(draft);results.push(correct);document.querySelector('#lesson9ExperienceFeedback'+i+'-'+j).textContent=correct?'✓ Chính xác':'Mẫu tham khảo: '+lesson9ExperienceVariants(i,j)[0]+'。';}state.lesson9Exercises=state.lesson9Exercises||{};state.lesson9Exercises.experiences=state.lesson9Exercises.experiences||{};state.lesson9Exercises.experiences[i]={drafts,results};save();});}
function lesson9InterviewReport(p){const name=p.name||'小明',v=p.action||'去',o=p.object||'长城',time=p.time||'去年',place=p.place?'在'+p.place:'',feeling=p.feeling||'很长，很美';return name+v+'过'+o+'，是'+time+place+v+'的，觉得'+o+feeling+'。';}
render();
